<script setup>
import {computed,ref} from 'vue';
import {createWorkflowNode} from '../../../../src/shared/product-workflow.js';
import {workflowTemplateFields,workflowNodeOutputs} from '../../../../src/shared/product-workflow-bindings.js';
import {isWorkflowInput} from '../../../../src/shared/product-workflow-inputs.js';
import WorkflowMaterialInput from './WorkflowMaterialInput.vue';
const props=defineProps({definition:{type:Object,required:true},category:{type:Object,required:true}}),emit=defineEmits(['navigate','upload']);
const search=ref(''),pendingOnly=ref(false),richOpen=ref(false);
const fields=computed(()=>workflowTemplateFields(props.category));
const contentKeys=['title','tags','description','images','richContent'];
const contents=computed(()=>fields.value.filter(f=>contentKeys.includes(f.key)));
const attributes=computed(()=>fields.value.filter(f=>!contentKeys.includes(f.key)&&f.label.toLowerCase().includes(search.value.toLowerCase())&&(!pendingOnly.value||!sources(f).length)));
const outputs=computed(()=>props.definition.nodes.flatMap(workflowNodeOutputs));
const sources=f=>props.definition.bindings[f.key]?.sources||[];
const nodeFor=f=>props.definition.nodes.find(n=>n.id===sources(f)[0]?.nodeId);
const labelFor=s=>outputs.value.find(o=>o.nodeId===s.nodeId&&o.output===s.output)?.label||'来源不可用';
const kindFor=f=>{const n=nodeFor(f);return !n?'':isWorkflowInput(n)?n.valueSource==='engineer'?'fixed':'user':n.type;};
const compatible=(o,f)=>f.kind==='rich'||(f.kind==='images'?o.kind==='image':o.kind==='text');
function assign(f,id){props.definition.bindings[f.key]={sources:id?outputs.value.filter(o=>`${o.nodeId}:${o.output}`===id).map(({nodeId,output})=>({nodeId,output})):[]};}
function changeSource(f,kind){
 if(!kind){props.definition.bindings[f.key]={sources:[]};return;}
 if(['copy','image'].includes(kind)){props.definition.bindings[f.key]={sources:[]};return;}
 const old=nodeFor(f);
 // A shared source can feed other fields: create a separate input instead of mutating it.
 const shared=old&&Object.entries(props.definition.bindings).some(([k,b])=>k!==f.key&&b.sources.some(s=>s.nodeId===old.id));
 let node=old&&isWorkflowInput(old)&&!shared?old:null;
 if(!node){node=f.attribute?JSON.parse(JSON.stringify(f.attribute)):createWorkflowNode('field');node.id=createWorkflowNode('field').id;Object.assign(node,{label:f.label,inputs:[],required:false,scope:'shared',defaultValue:'',inputFormat:f.kind==='number'?'number':'text'});const i=props.definition.nodes.findIndex(n=>['image','copy','approval'].includes(n.type));props.definition.nodes.splice(i<0?props.definition.nodes.length:i,0,node);}
 if(f.kind==='number')node.inputFormat='number';node.valueSource=kind==='fixed'?'engineer':'user';if(kind==='user')node.defaultValue='';props.definition.bindings[f.key]={sources:[{nodeId:node.id,output:'value'}]};
}
const chosenTypes=ref({});
function selectSource(f,kind){chosenTypes.value[f.key]=kind;changeSource(f,kind);}
function configureCopy(f){if(!nodeFor(f)){const n={...createWorkflowNode('copy'),label:f.label,target:'text',prompt:`基于已确认产品事实生成“${f.label}”，只返回本字段的值；字典字段仅使用类目允许的选项。`,inputs:props.definition.nodes.filter(n=>isWorkflowInput(n)&&n.type!=='images'&&n.valueSource!=='generated').map(n=>n.id)};props.definition.nodes.push(n);props.definition.bindings[f.key]={sources:[{nodeId:n.id,output:'text'}]};}navigate(f);}
function navigate(f){const n=nodeFor(f);emit('navigate',{mode:n?.type==='image'||f.key==='images'?'images':'text',nodeId:n?.id||''});}
</script>
<template><div class="attribute-workspace"><section class="content-links"><div class="section-head"><h3>商品内容 · 自动关联</h3><small>图片与文案只在对应模板中编辑</small></div><div class="content-grid"><article v-for="f in contents" :key="f.key"><strong>{{ f.label }}</strong><span>{{ sources(f).map(labelFor).join(' ＋ ')||'尚未关联' }}</span><el-button link type="primary" @click="f.key==='richContent'?richOpen=!richOpen:navigate(f)">{{ f.key==='richContent'?'调整组合':'前往编辑' }}</el-button></article></div><div v-if="richOpen" class="rich-editor"><label>富文本按所选图片和文字自动组合</label><el-select :model-value="sources(contents.find(f=>f.key==='richContent')).map(s=>`${s.nodeId}:${s.output}`)" multiple filterable @update:model-value="definition.bindings.richContent={sources:$event.map(key=>outputs.find(o=>`${o.nodeId}:${o.output}`===key)).map(({nodeId,output})=>({nodeId,output}))}"><el-option v-for="o in outputs" :key="`${o.nodeId}:${o.output}`" :value="`${o.nodeId}:${o.output}`" :label="o.label"/></el-select><small>成品图文可在“试用流程”的生产结果中预览。</small></div></section>
<section class="attribute-list"><div class="section-head"><h3>属性配置</h3><el-input v-model="search" clearable placeholder="搜索售价、包装或类目属性"/><el-checkbox v-model="pendingOnly">仅看待配置</el-checkbox></div><el-table :data="attributes" height="100%" row-key="key"><el-table-column label="属性" min-width="180"><template #default="{row}">{{ row.label }}<el-tag v-if="row.attribute?.platformRequired" size="small" type="info">平台必填</el-tag></template></el-table-column><el-table-column label="填写方式" width="170"><template #default="{row}"><el-select :model-value="kindFor(row)||chosenTypes[row.key]||''" @change="selectSource(row,$event)"><el-option label="暂不配置" value=""/><el-option label="用户填写" value="user"/><el-option label="模板固定" value="fixed"/><el-option label="AI 文本生成" value="copy"/></el-select></template></el-table-column><el-table-column label="值 / 规则" min-width="320"><template #default="{row}"><WorkflowMaterialInput v-if="kindFor(row)==='fixed'" v-model="nodeFor(row).defaultValue" :node="nodeFor(row)" :category="category" compact @options="nodeFor(row).options=$event" @upload="(file,index)=>emit('upload',file,nodeFor(row),index)"/><el-input v-else-if="kindFor(row)==='user'" v-model="nodeFor(row).help" placeholder="使用模板时填写；可在此补充填写说明"/><div v-else-if="kindFor(row)==='copy'||chosenTypes[row.key]==='copy'" class="generated-source"><el-select :model-value="sources(row)[0]?`${sources(row)[0].nodeId}:${sources(row)[0].output}`:''" filterable placeholder="选择文案节点输出" @change="assign(row,$event)"><el-option v-for="o in outputs.filter(o=>compatible(o,row)&&definition.nodes.find(n=>n.id===o.nodeId)?.type==='copy')" :key="`${o.nodeId}:${o.output}`" :label="o.label" :value="`${o.nodeId}:${o.output}`"/></el-select><el-button link type="primary" @click="configureCopy(row)">{{ nodeFor(row)?'编辑文案':'新建文案' }}</el-button></div><span v-else class="muted">可先保存模板，上架前再补充</span></template></el-table-column></el-table></section></div></template>
<style scoped>.attribute-workspace{height:100%;min-height:0;display:flex;flex-direction:column;gap:14px}.content-links,.attribute-list{border:1px solid var(--el-border-color-lighter);border-radius:10px;padding:14px;background:var(--el-bg-color)}.section-head{display:flex;align-items:center;gap:14px;margin-bottom:12px}.section-head h3{font-size:14px;margin:0;flex-shrink:0}.section-head .el-input{max-width:340px;margin-left:auto}.section-head small,.muted,small{color:var(--el-text-color-secondary);font-size:12px}.content-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.content-grid article{min-width:0;padding:10px;border-radius:6px;background:var(--el-fill-color-light);display:flex;flex-direction:column;align-items:flex-start;gap:8px}.content-grid strong{font-size:13px}.content-grid span{font-size:12px;color:var(--el-text-color-secondary);overflow-wrap:anywhere;max-height:54px;overflow:auto}.content-grid .el-button{margin-top:auto}.attribute-list{flex:1;min-height:260px;display:flex;flex-direction:column}.attribute-list .el-table{flex:1}.generated-source{display:flex;gap:10px}.el-select{width:100%}.rich-editor{display:grid;gap:8px;margin-top:12px}.attribute-list .el-tag{margin-left:6px}@media(max-width:900px){.content-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.section-head{flex-wrap:wrap}}
</style>
